import{_ as e,a0 as a,w as o,s as p,I as n,x as i,a1 as s,A as u,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在 Linux 下安装安卓文件传输助手 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 下安装安卓文件传输助手 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 下安装安卓文件传输助手 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 下安装安卓文件传输助手 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171124 How to Install Android File Transfer for Linux","title":"如何在 Linux 下安装安卓文件传输助手","tag":"201712","desc":""},"relativePath":"201712/20171124 How to Install Android File Transfer for Linux.md","filePath":"[post].md"}'),d={name:"201712/20171124 How to Install Android File Transfer for Linux.md"};function f(g,t,x,m,b,w){const l=a("Link");return o(),p("div",null,[t[19]||(t[19]=n("h1",{id:"如何在-linux-下安装安卓文件传输助手",tabindex:"-1"},[i("如何在 Linux 下安装安卓文件传输助手 "),n("a",{class:"header-anchor",href:"#如何在-linux-下安装安卓文件传输助手","aria-label":"Permalink to “如何在 Linux 下安装安卓文件传输助手”"},"​")],-1)),t[20]||(t[20]=n("p",null,"如果你尝试在 Ubuntu 下连接你的安卓手机，你也许可以试试 Linux 下的安卓文件传输助手。",-1)),t[21]||(t[21]=n("p",null,"本质上来说，这个应用是谷歌 macOS 版本的一个克隆。它是用 Qt 编写的，用户界面非常简洁，使得你能轻松在 Ubuntu 和安卓手机之间传输文件和文件夹。",-1)),t[22]||(t[22]=n("p",null,"现在，有可能一部分人想知道有什么是这个应用可以做，而 Nautilus（Ubuntu 默认的文件资源管理器）不能做的，答案是没有。",-1)),n("p",null,[t[2]||(t[2]=i("当我将我的 Nexus 5X（记得选择 ",-1)),s(l,{href:"https://en.wikipedia.org/wiki/Media_Transfer_Protocol"},{default:u(()=>[...t[0]||(t[0]=[i("媒体传输协议 MTP",-1)])]),_:1}),t[3]||(t[3]=i(" 选项）连接在 Ubuntu 上时，在 ",-1)),s(l,{href:"https://en.wikipedia.org/wiki/GVfs"},{default:u(()=>[...t[1]||(t[1]=[i("GVfs",-1)])]),_:1}),t[4]||(t[4]=i("（LCTT 译注： GNOME 桌面下的虚拟文件系统）的帮助下，我可以打开、浏览和管理我的手机，就像它是一个普通的 U 盘一样。",-1))]),n("p",null,[s(l,{href:"http://www.omgubuntu.co.uk/wp-content/uploads/2017/11/browsing-android-mtp-nautilus.jpg"},{default:u(()=>[...t[5]||(t[5]=[n("img",{src:"http://www.omgubuntu.co.uk/wp-content/uploads/2017/11/browsing-android-mtp-nautilus.jpg",alt:"Nautilus MTP integration with a Nexus 5X"},null,-1)])]),_:1})]),t[23]||(t[23]=r('<p>但是<em>一些</em>用户在使用默认的文件管理器时，在 MTP 的某些功能上会出现问题：比如文件夹没有正确加载，创建新文件夹后此文件夹不存在，或者无法在媒体播放器中使用自己的手机。</p><p>这就是要为 Linux 系统用户设计一个安卓文件传输助手应用的原因，将这个应用当做将 MTP 设备安装在 Linux 下的另一种选择。如果你使用 Linux 下的默认应用时一切正常，你也许并不需要尝试使用它 (除非你真的很想尝试新鲜事物)。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2017/11/android-file-transfer-for-linux-750x662.jpg" alt="Android File Transfer Linux App"></p><p>该 app 特点：</p><ul><li>简洁直观的用户界面</li><li>支持文件拖放功能（从 Linux 系统到手机）</li><li>支持批量下载 (从手机到 Linux系统)</li><li>显示传输进程对话框</li><li>FUSE 模块支持</li><li>没有文件大小限制</li><li>可选命令行工具</li></ul><h3 id="ubuntu-下安装安卓手机文件助手的步骤" tabindex="-1">Ubuntu 下安装安卓手机文件助手的步骤 <a class="header-anchor" href="#ubuntu-下安装安卓手机文件助手的步骤" aria-label="Permalink to “Ubuntu 下安装安卓手机文件助手的步骤”">​</a></h3><p>以上就是对这个应用的介绍，下面是如何安装它的具体步骤。</p><p>这有一个 [PPA]（个人软件包集）源为 Ubuntu 14.04 LTS、16.04 LTS 和 Ubuntu 17.10 提供可用应用。</p><p>为了将这一 PPA 加入你的软件资源列表中，执行这条命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:samoilov-lex/aftl-stable</span></span></code></pre></div><p>接着，为了在 Ubuntu 下安装 Linux版本的安卓文件传输助手，执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update &amp;&amp; sudo apt install android-file-transfer</span></span></code></pre></div><p>这样就行了。</p><p>你会在你的应用列表中发现这一应用的启动图标。</p><p>在你启动这一应用之前，要确保没有其他应用（比如 Nautilus）已经挂载了你的手机。如果其它应用正在使用你的手机，就会显示“无法找到 MTP 设备”。要解决这一问题，将你的手机从 Nautilus（或者任何正在使用你的手机的应用）上移除，然后再重新启动安卓文件传输助手。</p><hr>',16)),n("p",null,[t[7]||(t[7]=i("via: ",-1)),s(l,{href:"http://www.omgubuntu.co.uk/2017/11/android-file-transfer-app-linux"},{default:u(()=>[...t[6]||(t[6]=[i("http://www.omgubuntu.co.uk/2017/11/android-file-transfer-app-linux",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=i("作者：",-1)),s(l,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:u(()=>[...t[8]||(t[8]=[i("JOEY SNEDDON",-1)])]),_:1}),t[12]||(t[12]=i(" 译者：",-1)),s(l,{href:"https://github.com/wenwensnow"},{default:u(()=>[...t[9]||(t[9]=[i("wenwensnow",-1)])]),_:1}),t[13]||(t[13]=i(" 校对：",-1)),s(l,{href:"https://github.com/wxy"},{default:u(()=>[...t[10]||(t[10]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=i("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[14]||(t[14]=[i("LCTT",-1)])]),_:1}),t[17]||(t[17]=i(" 原创编译，",-1)),s(l,{href:"https://linux.cn/"},{default:u(()=>[...t[15]||(t[15]=[i("Linux中国",-1)])]),_:1}),t[18]||(t[18]=i(" 荣誉推出",-1))])])}const C=e(d,[["render",f]]);export{L as __pageData,C as default};
